import { IconButton, cn, useI18n } from '@gntik-ai/ui';
import { ArrowDown } from 'lucide-react';
import { useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode, type Ref } from 'react';
import { useChatScroll } from '../useChatScroll';
import { chatLayoutStyles as s } from './chatLayout.variants';

export interface ChatLayoutProps {
  /** The messages (ChatMessage list, suggestions, …). */
  children?: ReactNode;
  /** Pinned at the bottom of the thread column, outside the scroll area (usually ChatComposer). */
  composer?: ReactNode;
  /** Optional header above the thread (title, model, actions). */
  header?: ReactNode;
  /** Optional side panel (artifact preview, details). Omit to hide it and its resize handle. */
  panel?: ReactNode;
  /** Accessible name of the side panel landmark. */
  panelLabel?: string;
  /** Initial panel width in px. */
  defaultPanelWidth?: number;
  minPanelWidth?: number;
  maxPanelWidth?: number;
  onPanelWidthChange?: (width: number) => void;
  /** Accessible name of the thread region. */
  label?: string;
  /** Label of the "jump to latest" button. */
  scrollButtonLabel?: string;
  /** Extra classes on the root. */
  className?: string;
  /** Extra classes on the centred content column. */
  contentClassName?: string;
  ref?: Ref<HTMLDivElement>;
}

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));
const isRtl = (el: Element) => getComputedStyle(el).direction === 'rtl';

/**
 * Full-height chat frame: a scrollable thread with auto-scroll that respects scrolling up,
 * a "jump to latest" button, the composer pinned below, and an optional side panel that the
 * user can resize by dragging or with the arrow keys on its separator.
 */
export function ChatLayout({
  children,
  composer,
  header,
  panel,
  panelLabel: panelLabelProp,
  defaultPanelWidth = 380,
  minPanelWidth = 260,
  maxPanelWidth = 720,
  onPanelWidthChange,
  label: labelProp,
  scrollButtonLabel: scrollButtonLabelProp,
  className,
  contentClassName,
  ref,
}: ChatLayoutProps) {
  const { t } = useI18n();
  const panelLabel = panelLabelProp ?? t('chat.details');
  const label = labelProp ?? t('chat.conversation');
  const scrollButtonLabel = scrollButtonLabelProp ?? t('chat.scrollToBottom');
  const { scrollRef, contentRef, isAtBottom, scrollToBottom } = useChatScroll();
  const [width, setWidth] = useState(() => clamp(defaultPanelWidth, minPanelWidth, maxPanelWidth));
  const [dragging, setDragging] = useState(false);
  const drag = useRef<{ x: number; width: number; sign: number } | null>(null);

  const resize = (next: number) => {
    const w = clamp(Math.round(next), minPanelWidth, maxPanelWidth);
    setWidth(w);
    onPanelWidthChange?.(w);
  };

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    drag.current = { x: e.clientX, width, sign: isRtl(e.currentTarget) ? -1 : 1 };
    setDragging(true);
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (!drag.current) return;
    // The panel sits on the inline end (right in LTR): dragging toward the thread widens it.
    resize(drag.current.width + (drag.current.x - e.clientX) * drag.current.sign);
  };
  const endDrag = () => {
    drag.current = null;
    setDragging(false);
  };
  const onHandleKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const step = (e.shiftKey ? 64 : 16) * (isRtl(e.currentTarget) ? -1 : 1);
    const actions: Record<string, () => void> = {
      ArrowLeft: () => resize(width + step),
      ArrowRight: () => resize(width - step),
      Home: () => resize(maxPanelWidth),
      End: () => resize(minPanelWidth),
    };
    const action = actions[e.key];
    if (action) {
      e.preventDefault();
      action();
    }
  };

  return (
    <div ref={ref} className={cn(s.root, className)}>
      <section aria-label={label} className={s.thread}>
        {header && <div className={s.header}>{header}</div>}
        <div className={s.viewport}>
          <div ref={scrollRef} tabIndex={0} aria-label={t('chat.messages')} role="region" className={s.scroller}>
            <div ref={contentRef} className={cn(s.content, contentClassName)}>
              {children}
            </div>
          </div>
          {!isAtBottom && (
            <div className={s.jump}>
              <IconButton
                icon={ArrowDown}
                label={scrollButtonLabel}
                variant="secondary"
                size="sm"
                className={s.jumpButton}
                onClick={() => scrollToBottom()}
              />
            </div>
          )}
        </div>
        {composer && (
          <div className={s.composer}>
            <div className={s.composerInner}>{composer}</div>
          </div>
        )}
      </section>
      {panel && (
        <>
          <div
            role="separator"
            aria-orientation="vertical"
            aria-label={t('chat.resizePanel', { panel: panelLabel.toLowerCase() })}
            aria-valuenow={width}
            aria-valuemin={minPanelWidth}
            aria-valuemax={maxPanelWidth}
            tabIndex={0}
            data-dragging={dragging || undefined}
            className={s.handle}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
            onKeyDown={onHandleKey}
          />
          <aside aria-label={panelLabel} className={s.panel} style={{ width }}>
            {panel}
          </aside>
        </>
      )}
    </div>
  );
}

export { ChatLayout, type ChatLayoutProps } from './ChatLayout';
export { chatLayoutStyles } from './chatLayout.variants';
export { doc as chatLayoutDoc } from './ChatLayout.doc';

import { useCallback, useEffect, useRef, useState } from 'react';

export interface UseChatScrollOptions {
  /** Distance from the bottom (px) still treated as "at the bottom". */
  threshold?: number;
}

export interface UseChatScrollResult {
  /** Callback ref for the scrolling element. */
  scrollRef: (el: HTMLElement | null) => void;
  /** Callback ref for the content inside it (watched for growth, e.g. streamed tokens). */
  contentRef: (el: HTMLElement | null) => void;
  /** True while the viewport is pinned to the latest message. */
  isAtBottom: boolean;
  /** Scrolls to the latest message and re-pins auto-scroll. */
  scrollToBottom: (behavior?: ScrollBehavior) => void;
}

/** Imperative DOM write kept outside the hook (state values must not be mutated in place). */
function pinToBottom(el: HTMLElement) {
  el.scrollTop = el.scrollHeight;
}

function distanceFromBottom(el: HTMLElement) {
  return el.scrollHeight - el.scrollTop - el.clientHeight;
}

/**
 * Auto-scroll for a chat thread that respects the reader: new content keeps the view pinned
 * to the bottom only while the user is already there. Scrolling up unpins it (and
 * `isAtBottom` turns false, so a "scroll to latest" button can show); `scrollToBottom()`
 * pins it again.
 */
export function useChatScroll({ threshold = 48 }: UseChatScrollOptions = {}): UseChatScrollResult {
  const [scrollEl, setScrollEl] = useState<HTMLElement | null>(null);
  const [contentEl, setContentEl] = useState<HTMLElement | null>(null);
  const [isAtBottom, setIsAtBottom] = useState(true);
  const pinned = useRef(true);
  const lastTop = useRef(0);

  useEffect(() => {
    if (!scrollEl) return;
    lastTop.current = scrollEl.scrollTop;
    const onScroll = () => {
      const top = scrollEl.scrollTop;
      // Re-pin at the bottom; unpin only when the reader moves up (a smooth programmatic
      // scroll towards the bottom passes through "not at bottom" without unpinning).
      if (distanceFromBottom(scrollEl) <= threshold) pinned.current = true;
      else if (top < lastTop.current) pinned.current = false;
      lastTop.current = top;
      setIsAtBottom(pinned.current);
    };
    scrollEl.addEventListener('scroll', onScroll, { passive: true });
    return () => scrollEl.removeEventListener('scroll', onScroll);
  }, [scrollEl, threshold]);

  useEffect(() => {
    if (!scrollEl) return;
    const follow = () => {
      if (!pinned.current) return;
      pinToBottom(scrollEl);
      lastTop.current = scrollEl.scrollTop;
    };
    follow();
    const target = contentEl ?? scrollEl;
    const mo = new MutationObserver(follow);
    mo.observe(target, { childList: true, subtree: true, characterData: true });
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(follow) : undefined;
    ro?.observe(target);
    return () => {
      mo.disconnect();
      ro?.disconnect();
    };
  }, [scrollEl, contentEl]);

  const scrollToBottom = useCallback(
    (behavior: ScrollBehavior = 'smooth') => {
      if (!scrollEl) return;
      pinned.current = true;
      setIsAtBottom(true);
      const reduce = typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (typeof scrollEl.scrollTo === 'function') {
        scrollEl.scrollTo({ top: scrollEl.scrollHeight, behavior: reduce ? 'auto' : behavior });
      } else {
        pinToBottom(scrollEl);
      }
    },
    [scrollEl],
  );

  return { scrollRef: setScrollEl, contentRef: setContentEl, isAtBottom, scrollToBottom };
}
